{% extends "base.html" %}
{% load static %}

{% block title %}Sign in · Huginn{% endblock %}

{% block navbar %}{% endblock navbar %}

{% block content %}
{% include "ui/mockups/_screen_anchor.html" with screen_id="AUTH-LOGIN-1" screen_testid="auth-login-loaded" %}

<div class="row justify-content-center align-items-center" style="min-height:calc(100vh - 4rem)">
  <div class="col-md-10 col-lg-6 col-xl-5 col-xxl-4">
    <div class="text-center mb-4">
      <img src="{% static 'img/Huginn.jpeg' %}" alt="Huginn" width="64" height="64" class="rounded-2 mb-3 bg-white p-2 shadow-sm" data-testid="login-brand-mark">
      <h1 class="hg-page-title">Huginn</h1>
      <p class="text-muted small mb-0">Human-AI Command Composite</p>
    </div>
    <div class="card border-0 shadow-sm">
      <div class="card-body p-4">
        {% if messages %}
          {% for message in messages %}
            <div class="alert alert-info alert-dismissible fade show" role="alert" data-testid="login-flash-message">
              {{ message }}
              <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
            </div>
          {% endfor %}
        {% endif %}
        {% if login_error %}
          <div class="alert alert-warning" role="alert" data-testid="login-inline-error">{{ login_error }}</div>
        {% endif %}
        {% if connectivity_error %}
          <div class="alert alert-danger" role="alert" data-testid="login-connectivity-error">{{ connectivity_error }}</div>
        {% endif %}
        <form class="vstack gap-3" method="post" action="" autocomplete="off" data-testid="login-form">
          {% csrf_token %}
          <div class="mb-2">
            <label for="login-email" class="form-label">Email</label>
            <input name="email" type="email" class="form-control" id="login-email" data-testid="login-email"
                   placeholder="you@company.com" required autocomplete="username"
                   value="{{ field_email|default:'' }}">
          </div>
          <div class="mb-2">
            <label for="login-password" class="form-label">Password</label>
            <input name="password" type="password" class="form-control" id="login-password" data-testid="login-password"
                   required autocomplete="current-password">
          </div>
          <button type="submit" class="btn btn-primary w-100 fw-semibold mt-2" data-bs-toggle="tooltip" title="Sign in"
                  data-testid="login-submit" id="login-submit-btn" disabled>
            <i class="fa-solid fa-right-to-bracket me-1"></i> Sign In
          </button>
        </form>
        <div class="text-center mt-3">
          <span class="d-inline-block" data-bs-toggle="tooltip" data-bs-title="Contact your admin">
            <button type="button" class="btn btn-link btn-sm disabled text-muted" tabindex="-1" disabled data-testid="forgot-password">Forgot password?</button>
          </span>
        </div>
      </div>
    </div>
  </div>
</div>
{% endblock %}

{% block extra_js %}
<script src="{% static 'js/login_form.js' %}"></script>
{% endblock %}

